from flask import Flask, request, g
import sqlite3

app = Flask(__name__)
DATABASE = 'todo.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
    return db

@app.route('/search', methods=['GET'])
def search():
    req = request.args.get('q')

    query = "SELECT * FROM items WHERE description LIKE ?"
    db = get_db()
    cursor = db.cursor()
    cursor.execute(query, ('%' + req + '%',))
    results = cursor.fetchall()

    if results:
        return results
    else:
        return 'No results found'

if __name__ == '__main__':
    app.run()
